const frameIdSchema={type:'integer',minimum:0,description:'Optional frame_id observed in read_page.frames. Default 0 selects the top document. expected_url always names the top tab; child documents are bound internally. Read the frame before using its screenshot. No guessed IDs or security bypass.'};
tools.find(t=>t.name==='read_page').inputSchema.properties.catalog={type:'object',description:'Optional read-only DOM catalog. Returns cards, not action snapshot IDs. Main document and open shadow roots only; iframe contents and slots are explicitly unsupported. No AX. Do not combine with group or legacy read limits/offsets. References require the latest catalog observation_id, expire after 60 seconds and on observed DOM mutations. Catalog reads do not renew or replace legacy action snapshots. Check coverage before concluding absence.',properties:{mode:{type:'string',enum:['overview','search','details','children']},text:{type:'string',minLength:1,maxLength:200},exact:{type:'boolean'},ref:{type:'string',minLength:1,maxLength:100},observation_id:{type:'string',minLength:1,maxLength:200},cursor:{type:'string',minLength:1,maxLength:200},limit:{type:'integer',minimum:1,maximum:50},max_nodes:{type:'integer',minimum:10,maximum:10000},timeout_ms:{type:'integer',minimum:10,maximum:250}},additionalProperties:false};
for(const name of ['read_page','screenshot','read_page_code','wait_for'])tools.find(t=>t.name===name).inputSchema.properties.frame_id={...frameIdSchema};
tools.find(t=>t.name==='read_page').inputSchema.properties.group={type:'object',description:'Read one observed deferred collection, or continue an overview through its returned group_page cursor. Use its group_id and the latest snapshot_id; subsequent portions use returned group_page.group_id and next_cursor with the new snapshot_id. Limit defaults to 50, max 100. DOM changes, expired/replaced snapshots or frame changes refuse continuation. No text_offset/element_offset with group.',properties:{snapshot_id:{type:'string',minLength:1,maxLength:100},group_id:{type:'string',minLength:1,maxLength:100},cursor:{type:'string',minLength:1,maxLength:100},limit:{type:'integer',minimum:1,maximum:100}},required:['snapshot_id','group_id'],additionalProperties:false};
tools.find(t=>t.name==='read_page').description='Read bounded rendered text and element metadata, omitting form values. Includes accessible same-origin HTTP(S) iframe contents and open Shadow DOM. coverage reports actual scope. Unread HTTP(S) frames are listed in frames; choose an observed frame_id to read one through permissioned isolated-world injection, including cross-origin frames. expected_url remains the top tab URL. Every new read supersedes earlier action snapshots, including another frame. Internal elements use the same prepare_action/execute_prepared_action and exact-retry protocol. Browser-denied frames, opaque documents and closed roots are not bypassed. Supported semantic collections are deferred as groups regardless of size; table headers outside row groups remain in the overview. Read group portions explicitly; native select options are returned separately. If the overview reaches 50 group descriptors, group_page provides the same cursor-based continuation for the remaining overview. Folding data does not waive action guards for visible or selected context. Counts are lower bounds, never inferred totals. Group reads replace action snapshots and return bounded content plus continuation. Check coverage, read_budget and truncation; partial observation does not authorize incomplete action guards.';
tools.find(t=>t.name==='press_key').description=tools.find(t=>t.name==='press_key').description.replace('MAIN-FRAME page element','page element, including a supported iframe or open Shadow DOM; enclosing frame focus is checked');
tools.find(t=>t.name==='act').description=tools.find(t=>t.name==='act').description.replace('main-frame contenteditable','supported-document contenteditable').replace('scrolls the main window','scrolls the observed document window');
tools.find(t=>t.name==='drag').description='Drag within one observed document using a reviewed PNG and the common preparation protocol. Includes supported iframe and open Shadow DOM targets. Both endpoints and the path must stay in that observed document; parent boundaries, overlays, target identity and geometry are checked. Left press, motion, best-effort release. Optional modifiers apply only during this operation. No OS file or cross-tab drag. Old allow_iframe is a compatibility field, not permission to bypass an unread frame. Verify actual effect; unknown or partial input must not be replayed.';
tools.find(t=>t.name==='screenshot').description+=' Optional observed frame_id captures that frame viewport as a native PNG, with local image coordinates; the whole frame viewport must be visible in its parent chain. Never mix top-page and frame coordinates. Subsequent preparation and input inherit the frame from snapshot_id.';
tools.find(t=>t.name==='wait_for').description+=' Optional observed frame_id keeps every read in that frame; omitted means the top document. wait_after inherits the dispatched action frame automatically.';
